{
  "findings": [
    {
      "check_id": "CKV_AWS_70",
      "title": "S3 bucket policy does not enforce encrypted transport",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "HIGH",
      "explanation": "The policy does not deny requests made without TLS, allowing S3 operations to be attempted over unencrypted HTTP connections."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Malformed S3 bucket policy",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "MEDIUM",
      "explanation": "The embedded policy is missing a comma between Principal and Effect, so AWS would reject the policy and its intended deny control would not be applied."
    }
  ],
  "patched_code": "resource "aws_s3_bucket_policy" "pass3" {
  bucket = "bucket"

  policy = jsonencode({
    Id      = "Policy1597273448050"
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Stmt1597273446725"
        Action = ["s3:GetObject"]
        Resource = "arn:aws:s3:::bucket/*"
        Principal = {
          AWS = "some_arn"
        }
        Effect = "Deny"
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:aws:s3:::bucket",
          "arn:aws:s3:::bucket/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}
",
  "fix_summary": "Converted the malformed heredoc policy to jsonencode and added an explicit deny for all S3 requests made without secure transport. The existing deny statement and resource were retained."
}
